python3 -c "
import json
with open('/app/resources/treasury_bulletin_1980_11.json', 'r') as f:
    data = json.load(f)

# Let's see the structure
def find_key(obj, target):
    if isinstance(obj, dict):
        for k, v in obj.items():
            if 'savings' in k.lower() and 'notes' in k.lower():
                print(f'Found: {k}')
            if isinstance(v, (dict, list)):
                find_key(v, target)
    elif isinstance(obj, list):
        for item in obj:
            find_key(item, target)

find_key(data, 'savings notes')
"
